// 1. Get raw output from AI Agent
let rawOutput = $json.output || "";

// 2. Strip markdown fences
let cleaned = rawOutput.replace(/```json|```/g, "").trim();

// 3. Parse JSON safely
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error("Failed to parse AI output as JSON: " + err.message + "\nCleaned string:\n" + cleaned);
}

// 4. Normalize each docket item to standard schema
const normalized = parsed.map(item => ({
  item_number: item.item_number || null,
  summary_of_application: item.summary_of_application || null,
  zoning_request: item.zoning_request || null,
  staff_recommendation: item.staff_recommendation || null,
  applicant: item.applicant || null,
  representative: item.representative || null,
  planner: item.city_planner || item.planner || null, // map city_planner → planner
  council_district: item.council_district || null,
  attachments: item.attachments || [] // always array
}));

// 5. Return each docket entry as separate n8n item
return normalized.map(obj => ({ json: obj }));
